const ROLE_IDS = ["market_data", "earnings_deep_dive", "forward_expectations", "quant_factor", "valuation_long_short", "news_industry_management", "insider_sec", "ib_event_analysis", "macro_regime", "market_narrative", "social_pulse", "source_fidelity", "rederivation", "refuter"];

export function selectionDisplay(locale, personaId) {
  const copy = COPY[locale];
  if (!copy) return null;
  const role = ROLE_IDS.indexOf(personaId);
  if (role >= 0) return { title: copy.roles[role] };
  const index = METHODS.findIndex(([id]) => `master_${id}` === personaId);
  if (index < 0) return null;
  const name = METHODS[index][1];
  const title = name ? copy.title(name) : copy.forensic;
  const [method, best_for] = copy.rows[index];
  return { title, identity: `${title}; ${copy.identity}`, method, best_for };
}

