const INTERFACE = Object.fromEntries(Object.keys(COPY).map((locale) => [locale, {}]));
for (const row of INTERFACE_ROWS.trim().split("\n")) {
  const [key, ...values] = row.split("|");
  for (const [index, locale] of Object.keys(COPY).entries()) {
    const [group, field] = key.split(".");
    if (field) (INTERFACE[locale][group] ||= {})[field] = values[index];
    else INTERFACE[locale][group] = values[index];
  }
}

export function selectionInterfaceCopy(language) {
  return INTERFACE[languageKey(language)] || null;
}
